root=Path(__file__).resolve().parents[2];p=root/'research/nine-sharing-sign15-rank-value-check';draft=root/'research/nine-sharing-sign15-rank-value-draft';sha=lambda q:hashlib.sha256(q.read_bytes()).hexdigest();run=p/'run.py';m=p/'source-manifest.json';assert sha(run)=='1c09fb9ed3f596939ae7bdcc08d1aab630f9c191868522ef2a0e6459a3cc345e' and sha(m)=='7158e716fe536be277f02da48f3b5874e0791c3d056bc31607c995ad6e3a2183';row,=json.loads(m.read_text())['rows'];name='Sign15RankValue';src=p/'src/DiophantineConsistency'/(name+'.lean');s=src.read_text();assert sha(src)==sha(draft/(name+'.lean'))==row['source_sha256']=='5f66111f5689014806a9f95a83ead13633f2cf39ab8adc0d093da02bc89072e4' and row['module']=='DiophantineConsistency.'+name and re.findall(r'^import ([A-Za-z0-9_.]+)$',s,re.M)==row['imports']==['DiophantineConsistency.Sign15SharedValues'];assert not re.search(r'(?m)^\s*(axiom|opaque)\b|\b(sorry|admit)\b',s)
assert 'theorem rank_eval (p : Fin 4 → ℤ) (beta MC MF : V) (v : Fin 16 → V)' in s and all('(hp'+i+' : ((p '+i+' : ℤ) : DiffRing V) = ι ' in s for i in ('0','2','3')) and '(hqF : v 2 + 1 ≤ A beta v)' in s and '(shared25 p).evalRing' in s and '(shared14 p).evalRing' in s and 'ι (Rank beta MC MF v)' in s
r=run.read_text();assert "'-M2800'" in r and "'-j1'" in r and 'rss_limit=4*1024**3,mem_floor=10*1024**3,seconds=120,interval=.1' in r and 'free>=5_000_000_000' in r and 'matches=[x for x in base[\'rows\'] if x[\'module\']==local]' in r and "sha(P/'source-manifest.json')" in r
check=root/'reviews/nine-sharing-sign15-shared-values-terminal-independent/check.py';assert sha(check)=='ccdc3a78f9cff87a8e486c1ace0859a8204d86c1ac327be684529fea61fee303';subprocess.run([sys.executable,'-I','-S','-B',str(check)],capture_output=True,check=True,timeout=120)
x=subprocess.run([sys.executable,'-I','-S','-B',str(run),'--preflight'],capture_output=True,text=True,timeout=180);assert x.returncode==0 and not x.stderr and json.loads(x.stdout)['status']=='PASS_NO_LEAN_PREFLIGHT'
print(json.dumps({'status':'PASS_PRELAUNCH','runner_sha256':sha(run),'scope':'source-only rank representation conditional on represented ports and q ≥ F; no natural lift or bridge'},indent=2,sort_keys=True))
